CREATE TABLE IF NOT EXISTS velvet_roundtrip_checks (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,request_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS velvet_owner_entitlements (owner_user_id TEXT PRIMARY KEY,plan TEXT NOT NULL DEFAULT 'free',status TEXT NOT NULL DEFAULT 'active',updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS idx_velvet_owner_entitlements_plan ON velvet_owner_entitlements(plan,status);
CREATE TABLE IF NOT EXISTS velvet_owner_preferences (owner_user_id TEXT PRIMARY KEY,soon_alerts_enabled INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS velvet_customer_memories (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,customer_id TEXT NOT NULL,display_name_snapshot TEXT,personality_note TEXT,preference_note TEXT,caution_note TEXT,conversation_summary TEXT,last_interaction_summary TEXT,next_topic_hint TEXT,tags_json TEXT NOT NULL DEFAULT '[]',pinned INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(workspace_id,user_id,customer_id));
CREATE INDEX IF NOT EXISTS idx_velvet_customer_memories_scope ON velvet_customer_memories(workspace_id,user_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS velvet_professional_visits (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,customer_id TEXT NOT NULL,reservation_id TEXT,visit_schedule_id TEXT,visited_at TEXT NOT NULL,ended_at TEXT,duration_minutes INTEGER,service_context TEXT,seating_reason TEXT,conversation_memo TEXT,preference_memo TEXT,caution_memo TEXT,next_action_memo TEXT,summary TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_velvet_professional_visits_scope ON velvet_professional_visits(workspace_id,user_id,customer_id,visited_at DESC);
CREATE TABLE IF NOT EXISTS velvet_professional_timeline (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,customer_id TEXT NOT NULL,occurred_at TEXT NOT NULL,event_type TEXT NOT NULL,title TEXT NOT NULL,body TEXT,source_ref TEXT);
CREATE INDEX IF NOT EXISTS idx_velvet_timeline_scope ON velvet_professional_timeline(workspace_id,user_id,customer_id,occurred_at DESC);
CREATE TABLE IF NOT EXISTS velvet_professional_next_actions (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,customer_id TEXT NOT NULL,text TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL,due_at TEXT,completed_at TEXT,action_type TEXT,topic_id TEXT,timing TEXT,priority TEXT,source_capture_id TEXT,source_topic_id TEXT);
CREATE INDEX IF NOT EXISTS idx_velvet_next_actions_scope ON velvet_professional_next_actions(workspace_id,user_id,customer_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_velvet_next_actions_due ON velvet_professional_next_actions(workspace_id,user_id,status,due_at);
CREATE TABLE IF NOT EXISTS velvet_professional_captures (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,customer_id TEXT,kind TEXT NOT NULL,raw_text TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_velvet_captures_scope ON velvet_professional_captures(workspace_id,user_id,customer_id,created_at DESC);
CREATE TABLE IF NOT EXISTS velvet_notes (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,customer_id TEXT NOT NULL,visit_id TEXT,note_type TEXT NOT NULL DEFAULT 'professional_note',note_ref TEXT,body_preview TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS idx_velvet_notes_scope ON velvet_notes(workspace_id,user_id,customer_id,created_at DESC);
CREATE TABLE IF NOT EXISTS velvet_professional_gifts (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,customer_id TEXT NOT NULL,direction TEXT NOT NULL,item TEXT NOT NULL,occasion TEXT,memo TEXT,occurred_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_velvet_professional_gifts_scope ON velvet_professional_gifts(workspace_id,user_id,customer_id,occurred_at DESC);
CREATE TABLE IF NOT EXISTS velvet_professional_schedule_entries (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,customer_id TEXT,visit_schedule_id TEXT,entry_type TEXT NOT NULL,title TEXT NOT NULL,starts_at TEXT NOT NULL,note TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_velvet_professional_schedule_scope ON velvet_professional_schedule_entries(workspace_id,user_id,starts_at);
CREATE TABLE IF NOT EXISTS velvet_capture_dictionary (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,category TEXT NOT NULL,normalized_value TEXT NOT NULL,display_value TEXT NOT NULL,use_count INTEGER NOT NULL DEFAULT 1,last_used_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(workspace_id,user_id,category,normalized_value));
CREATE INDEX IF NOT EXISTS idx_velvet_capture_dictionary_scope ON velvet_capture_dictionary(workspace_id,user_id,use_count DESC,last_used_at DESC);
CREATE TABLE IF NOT EXISTS velvet_self_investments (id TEXT PRIMARY KEY,owner_user_id TEXT NOT NULL,occurred_at TEXT NOT NULL,category TEXT NOT NULL,amount INTEGER NOT NULL,memo TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_velvet_self_investments_owner ON velvet_self_investments(owner_user_id,occurred_at DESC);
CREATE TABLE IF NOT EXISTS velvet_professional_relationships (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,customer_a_id TEXT NOT NULL,customer_b_id TEXT NOT NULL,relation_type TEXT NOT NULL,note TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_velvet_professional_relationships_scope ON velvet_professional_relationships(workspace_id,user_id,created_at DESC);

CREATE TABLE IF NOT EXISTS velvet_conversation_episodes (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,customer_id TEXT NOT NULL,visit_id TEXT,capture_id TEXT NOT NULL,topic_id TEXT NOT NULL,label TEXT NOT NULL,content TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'new',occurred_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_velvet_conversation_episodes_customer ON velvet_conversation_episodes(workspace_id,user_id,customer_id,occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_velvet_conversation_episodes_topic ON velvet_conversation_episodes(workspace_id,user_id,customer_id,topic_id,occurred_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS idx_velvet_conversation_episode_capture_topic ON velvet_conversation_episodes(capture_id,topic_id,label,content);

CREATE TABLE IF NOT EXISTS velvet_ongoing_topics (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,user_id TEXT NOT NULL,customer_id TEXT NOT NULL,topic_id TEXT NOT NULL,label TEXT NOT NULL,latest_content TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'new',first_episode_id TEXT NOT NULL,latest_episode_id TEXT NOT NULL,first_seen_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,completed_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(workspace_id,user_id,customer_id,topic_id));
CREATE INDEX IF NOT EXISTS idx_velvet_ongoing_topics_customer ON velvet_ongoing_topics(workspace_id,user_id,customer_id,state,last_seen_at DESC);
